<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Conditions & Supports — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffdfb;--ink:#121212;--muted:#6b6b67;--accent:#4a86e8}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;background-image:url('assets/img/pattern.svg');background-size:220px}
