    p.lead{color:var(--muted);margin:0 0 18px}
    .list{display:grid;grid-template-columns:1fr 1fr;gap:14px}
    .cond{padding:12px;border-radius:8px;background:#fbfbfc;border:1px solid #f2f2f3}
    .cond h3{margin:0 0 6px;font-size:15px}
